/**
 * Pixoria admin icon picker — vanilla JS, no dependencies.
 *
 * Wired by IconPickerWidget (apps/core/icon_utils.py). Each picker root is a
 *   <div class="icon-picker" data-icon-picker>
 * with an input (data-ip-input), a preview button (data-ip-preview), an error
 * line and a popup (data-ip-popup) holding a search box and a grid.
 *
 * Icons come from window.__TI_ICONS, a flat list of Tabler Icons names
 * generated by scripts/build_tabler_icons.py from the bundled webfont CSS.
 * Rendering an icon is just <i class="ti ti-rocket"> — no sprite, nothing
 * to sync.
 */
(function () {
  "use strict";

  var ALL = window.__TI_ICONS || [];
  var ALIASES = window.__TI_ALIASES || {};
  var MAX_ITEMS = 240;

  // نام‌های قدیمیِ Lucide/Font Awesome به معادلِ Tabler نگاشت می‌شوند —
  // همان کاری که map_icon_name در سمتِ سرور انجام می‌دهد.
  function normalize(name) {
    return ALIASES[name] || name;
  }

  function iconFor(name) {
    var el = document.createElement("i");
    el.className = "ti ti-" + name;
    el.setAttribute("aria-hidden", "true");
    return el;
  }

  function matches(name, query) {
    if (!query) return true;
    // جستجوی ساده: هر کلمهٔ جستجو باید در نام آیکون باشد
    return query
      .toLowerCase()
      .split(/\s+/)
      .every(function (part) {
        return name.indexOf(part) !== -1;
      });
  }

  function init(root) {
    var input = root.querySelector("[data-ip-input]");
    var previewBtn = root.querySelector("[data-ip-preview]");
    var popup = root.querySelector("[data-ip-popup]");
    var search = root.querySelector("[data-ip-search]");
    var grid = root.querySelector("[data-ip-grid]");
    var count = root.querySelector("[data-ip-count]");
    var error = root.querySelector("[data-ip-error]");
    if (!input || !previewBtn || !popup) return;

    var open = false;
    var names = [];

    /* ---- وضعیتِ فیلد: پیش‌نمایش + هشدار خطا ---- */
    function syncState() {
      var value = input.value.trim();
      var norm = normalize(value);
      previewBtn.textContent = "";
      if (value && ALL.indexOf(norm) !== -1) {
        previewBtn.appendChild(iconFor(norm));
        previewBtn.classList.remove("ip-empty");
      } else {
        previewBtn.textContent = "—";
        previewBtn.classList.add("ip-empty");
      }
      error.hidden = !(value && ALL.indexOf(norm) === -1);
    }

    /* ---- رندرِ جدولِ آیکون‌ها ---- */
    function renderGrid() {
      var query = search.value.trim();
      grid.textContent = "";
      names = [];
      var shown = 0;
      for (var i = 0; i < ALL.length && shown < MAX_ITEMS; i++) {
        var name = ALL[i];
        if (!matches(name, query)) continue;
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "ip-item";
        btn.dataset.name = name;
        btn.title = name;
        btn.appendChild(iconFor(name));
        grid.appendChild(btn);
        names.push(name);
        shown++;
      }
      var total = ALL.filter(function (n) {
        return matches(n, query);
      }).length;
      count.textContent =
        shown < total
          ? shown + " از " + total + " آیکون — جستجو را دقیق‌تر کنید"
          : total + " آیکون";
    }

    function openPopup() {
      if (open) return;
      open = true;
      popup.hidden = false;
      search.value = "";
      renderGrid();
      search.focus();
      document.addEventListener("mousedown", onOutside);
    }

    function closePopup() {
      if (!open) return;
      open = false;
      popup.hidden = true;
      document.removeEventListener("mousedown", onOutside);
    }

    function onOutside(e) {
      if (!root.contains(e.target)) closePopup();
    }

    function select(name) {
      input.value = name;
      syncState();
      closePopup();
      input.focus();
    }

    previewBtn.addEventListener("click", function () {
      if (open) closePopup();
      else openPopup();
    });

    search.addEventListener("input", renderGrid);

    search.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        closePopup();
        input.focus();
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        var first = grid.querySelector(".ip-item");
        if (first) first.focus();
      }
    });

    grid.addEventListener("click", function (e) {
      var btn = e.target.closest(".ip-item");
      if (btn) select(btn.dataset.name);
    });

    grid.addEventListener("keydown", function (e) {
      var items = [].slice.call(grid.querySelectorAll(".ip-item"));
      var idx = items.indexOf(document.activeElement);
      if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        e.preventDefault();
        items[Math.min(items.length - 1, idx + 1)].focus();
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        e.preventDefault();
        if (idx <= 0) search.focus();
        else items[idx - 1].focus();
      } else if (e.key === "Escape") {
        closePopup();
        input.focus();
      }
    });

    input.addEventListener("input", syncState);
    input.addEventListener("blur", function () {
      // هشدارها فقط بعد از ترکِ فیلد محو می‌شوند تا حین تایپ مزاحم نباشند
      syncState();
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && open) {
        closePopup();
        input.focus();
      }
    });

    syncState();
  }

  function initAll(scope) {
    (scope || document)
      .querySelectorAll("[data-icon-picker]:not([data-ip-ready])")
      .forEach(function (root) {
        root.dataset.ipReady = "";
        init(root);
      });
  }

  function boot() {
    initAll(document);
    // فرم‌های inlineِ ادمینِ داینامیک («افزودن ردیف دیگر») پیکرهای جدیدی
    // درست می‌کنند — این پیکرها هم باید راه‌اندازی شوند.
    if (typeof MutationObserver === "undefined") return;
    new MutationObserver(function (records) {
      for (var i = 0; i < records.length; i++) {
        var nodes = records[i].addedNodes;
        for (var j = 0; j < nodes.length; j++) {
          var node = nodes[j];
          if (node.nodeType === 1) initAll(node);
        }
      }
    }).observe(document.body, { childList: true, subtree: true });
  }

  // ادمینِ جنگو mediaی فرم را داخلِ <head> رندر می‌کند، پس این اسکریپت
  // می‌تواند قبل از ساختِ DOM اجرا شود — صبر تا اینکه صفحه parse شود.
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
